course_id = #{courseId}, chapter_id = #{chapterId}, video_id = #{videoId}, document_id = #{documentId}, title = #{title}, resource_type = #{resourceType}, content_summary = #{contentSummary}, source_url = #{sourceUrl}, value_theme = #{valueTheme}, applicable_scene = #{applicableScene}, keywords = #{keywords}, difficulty = #{difficulty}, status = #{status}, updated_at = CURRENT_TIMESTAMP
