SELECT * FROM ideology_resources

    AND course_id = #{courseId}
    AND status = #{status}

        AND (title LIKE CONCAT('%', #{keyword}, '%')
             OR content_summary LIKE CONCAT('%', #{keyword}, '%')
             OR keywords LIKE CONCAT('%', #{keyword}, '%')
             OR value_theme LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY updated_at DESC, resource_id DESC
LIMIT #{limit}

SELECT * FROM ideology_resources
WHERE status = 'published'
AND course_id = #{courseId}

    AND (

        keywords LIKE CONCAT('%', #{keyword}, '%')
        OR value_theme LIKE CONCAT('%', #{keyword}, '%')
        OR applicable_scene LIKE CONCAT('%', #{keyword}, '%')

    )

ORDER BY updated_at DESC, resource_id DESC
